"""RED oracle for ngv2.semgrep_adapter — deterministic injected-runner adapter
around the semgrep CLI. The tool is mocked via a runner callable; pure stdlib."""
import json

from ngv2.semgrep_adapter import build_semgrep_argv, run_semgrep


def test_build_semgrep_argv_shape():
    argv = build_semgrep_argv('repo/path', config='auto')
    assert argv[0] == 'semgrep'
    assert '--json' in argv and '--quiet' in argv
    assert '--config' in argv
    assert argv[argv.index('--config') + 1] == 'auto'
    assert argv[-1] == 'repo/path'


def test_build_semgrep_argv_custom_config():
    argv = build_semgrep_argv('t', config='p/security-audit')
    assert argv[argv.index('--config') + 1] == 'p/security-audit'


def test_run_semgrep_parses_runner_json():
    payload = {'results': [{'check_id': 'x'}], 'errors': []}
    calls = []

    def runner(argv):
        calls.append(argv)
        return (0, json.dumps(payload), '')

    out = run_semgrep('repo/path', runner=runner)
    assert out == payload
    # the runner was invoked with the built argv
    assert calls and calls[0][0] == 'semgrep' and calls[0][-1] == 'repo/path'


def test_run_semgrep_nonzero_rc_returns_empty_results():
    def runner(argv):
        return (2, '', 'boom')

    out = run_semgrep('t', runner=runner)
    assert out['results'] == []
    assert out.get('errors')  # error surfaced, not raised


def test_run_semgrep_bad_json_returns_empty_results():
    def runner(argv):
        return (0, 'not json', '')

    out = run_semgrep('t', runner=runner)
    assert out['results'] == []

